{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C29", "C08", "C14", "C10", "C62", "C45", "C68", "C92", "C82", "C100", "C119", "C141", "C133", "C138"],
  "contradictory_card_ids": ["C47", "C134", "C139", "C143", "C160", "C148", "C153", "C150", "C135", "C158"],
  "prediction_basis_card_ids": ["C29", "C08", "C14", "C10", "C62", "C45", "C68", "C92", "C82", "C100", "C119", "C141", "C133", "C138", "C134", "C139", "C143", "C153"],
  "claims": [
    {
      "claim": "Directly transferable nucleoside-analog contexts show measured oral F above 20%: zalcitabine ~80% in fasted patients (C29), didanosine fasting F 0.22–0.28 (C08, C14), zidovudine F 0.61±0.22 in cirrhosis (C10), zalcitabine 30% in fasted mice (C62), didanosine 42% (C45), and children mean F 0.27±0.13 (C68).",
      "card_ids": ["C29", "C08", "C14", "C10", "C62", "C45", "C68"]
    },
    {
      "claim": "L3 oral exposure records for structurally similar ribonucleosides show substantial systemic exposure after oral dosing, e.g., ribavirin AUC0-12 3325.83 ng·h/mL and Tmax 1.61 h (C92, C82), and lamivudine 300 mg AUC0-inf 13.2 µg·h/mL and Cmax 3.3 µg/mL (C100, C119).",
      "card_ids": ["C92", "C82", "C100", "C119"]
    },
    {
      "claim": "L4 shows high solubility for the closely related ribavirin across physiological pH (C141, C133, C138), supporting a favorable dissolution component for this polar nucleoside class.",
      "card_ids": ["C141", "C133", "C138"]
    },
    {
      "claim": "L4 also shows low Caco-2/PAMPA permeability for ribavirin (C134, C139, C143), levovirin (C160, C148), didanosine (C153), and gemcitabine (C150, C135, C158), but low passive permeability is not affirmative low-F evidence: didanosine has measured F ~22–42% despite low PAMPA, and ribavirin's low Caco-2 value is attributed to limited hCNT2 expression (C134), not necessarily poor in vivo absorption.",
      "card_ids": ["C134", "C139", "C143", "C160", "C148", "C153", "C150", "C135", "C158"]
    },
    {
      "claim": "The only sub-20% nucleoside F record, gemcitabine in mice (C47), is low-transferability and reflects a different metabolic liability; it does not overturn the high prediction for AICAR.",
      "card_ids": ["C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C141", "C133", "C138", "C134", "C139", "C143", "C160", "C148", "C153", "C150", "C135", "C158"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for AICAR/acadesine is present in the supplied records.",
    "No AICAR-specific permeability, transporter, or intestinal absorption experiment is present; L4 transfer is from ribavirin, levovirin, didanosine, and gemcitabine.",
    "L4 permeability assays are in vitro and may underrepresent nucleoside transporter-mediated absorption, e.g., hCNT2.",
    "No AICAR-specific first-pass metabolism or clearance data are available.",
    "Analog oral F values are variable, so population-level inference is uncertain."
  ],
  "decision_summary": "Predicted high (F >= 20%) because directly transferable nucleoside-analog contexts show measured F above 20% and L3 oral exposure records show substantial systemic exposure for structurally similar ribonucleosides. L4 adds high solubility for ribavirin and low in vitro permeability for several polar nucleosides, but low passive permeability is not affirmative low-F evidence and didanosine/ribavirin examples show that transporter-mediated absorption can still yield F >20%. No direct AICAR measurement is available, so confidence remains moderate."
}

